  function trigger() { ids.forEach(function(id){ var el=document.getElementById(id); if(el) el.classList.add('i3m-vis'); }); }
  if (document.readyState==='complete') { trigger(); } else { window.addEventListener('load', trigger); }
  var mainImg=document.getElementById('i3m-main-img');
  var thumbs=document.querySelectorAll('.i3m-hero__thumb');
  thumbs.forEach(function(thumb){
    thumb.addEventListener('click', function(){
      var src=thumb.getAttribute('data-src');
      if(src&&mainImg){mainImg.style.opacity='0';mainImg.style.transition='opacity 0.2s ease';setTimeout(function(){mainImg.src=src;mainImg.style.opacity='1';},180);}
      thumbs.forEach(function(t){t.classList.remove('i3m-hero__thumb--active');});
      thumb.classList.add('i3m-hero__thumb--active');
    });
  });
})();
