  ['i3m-tech-hdr','i3m-tech-plat','i3m-tech-feats','i3m-tech-apps-hdr','i3m-tech-apps'].forEach(function(id){
    var el=document.getElementById(id); if(el) obs.observe(el);
  });
})();
</script></div></div></div></div></div></div></div></section></div>
